<?php require_once(dirname(__DIR__) . '/init.php'); ?>
<?php
require_once(__DIR__ . '/../config.php');
require_once(__DIR__ . '/../includes/functions.php');
require_once(__DIR__ . '/../includes/audit_helpers.php');
requireLogin(); ensureAllowed('ruminant_daily');
$farmId=requireCurrentFarmId();
$canManage=isPlatformOwner()||hasRole('farm_admin')||hasRole('ruminant_manager');
$editId=(int)($_GET['edit']??0);
$editAnimal=null;
if($editId>0){ $eq=$pdo->prepare('SELECT * FROM ruminant_animals WHERE id=? AND farm_id=? LIMIT 1'); $eq->execute([$editId,$farmId]); $editAnimal=$eq->fetch(PDO::FETCH_ASSOC) ?: null; }
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!verify_csrf_token($_POST['csrf_token']??'')){ http_response_code(419); exit('Invalid request token.'); }
 if(!$canManage){ http_response_code(403); exit('Access denied.'); }
 $action=$_POST['action']??'';
 if($action==='save'){
  $id=(int)($_POST['id']??0); $tag=trim($_POST['tag_no']??''); $species=strtolower(trim($_POST['species']??'other'));
  $sex=strtolower(trim($_POST['sex']??'unknown')); $breed=trim($_POST['breed']??''); $birth=$_POST['birth_date']?:null;
  $source=trim($_POST['source']??''); $purchaseDate=$_POST['purchase_date']?:null; $purchaseCost=(float)($_POST['purchase_cost']??0); $status=$_POST['status']??'active'; $notes=trim($_POST['notes']??'');
  if($tag===''||!in_array($species,['cattle','goat','sheep','other'],true)||!in_array($sex,['male','female','unknown'],true)||!in_array($status,['active','sold','dead','culled','transferred'],true)||$purchaseCost<0) { exit('Invalid animal data.'); }
  // A tag is unique within a species, not across all ruminants. This allows, for example,
  // Cattle #1 and Goat #1 to coexist while preventing two cattle from both being #1.
  $dupSql='SELECT id FROM ruminant_animals WHERE farm_id=? AND species=? AND tag_no=? AND id<>? LIMIT 1';
  $dup=$pdo->prepare($dupSql); $dup->execute([$farmId,$species,$tag,$id]);
  if($dup->fetchColumn()){
    $_SESSION['error'] = 'Duplicate tag number: '.$tag.' already exists for a '.ucfirst($species).' in this farm. The same tag number can be used for a different species.';
    header('Location: animal_registry.php'); exit();
  }
  try {
   if($id>0){ $q=$pdo->prepare('SELECT * FROM ruminant_animals WHERE id=? AND farm_id=? LIMIT 1'); $q->execute([$id,$farmId]); $before=$q->fetch(PDO::FETCH_ASSOC); if(!$before){ $_SESSION['error']='Animal not found.'; header('Location: animal_registry.php'); exit(); }
    $q=$pdo->prepare('UPDATE ruminant_animals SET tag_no=?,species=?,breed=?,sex=?,birth_date=?,source=?,purchase_date=?,purchase_cost=?,status=?,notes=?,updated_at=NOW() WHERE id=? AND farm_id=?');
    $q->execute([$tag,$species,$breed?:null,$sex,$birth,$source?:null,$purchaseDate,$purchaseCost,$status,$notes?:null,$id,$farmId]); audit_log_event('update','ruminant_animal',$id,['before'=>$before,'after'=>$_POST]);
   } else { $q=$pdo->prepare('INSERT INTO ruminant_animals(farm_id,tag_no,species,breed,sex,birth_date,source,purchase_date,purchase_cost,status,notes,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)'); $q->execute([$farmId,$tag,$species,$breed?:null,$sex,$birth,$source?:null,$purchaseDate,$purchaseCost,$status,$notes?:null,$_SESSION['user_id']]); audit_log_event('create','ruminant_animal',$pdo->lastInsertId(),['tag_no'=>$tag,'species'=>$species]); }
  } catch (PDOException $e) {
    if ((int)$e->errorInfo[1] === 1062) {
      $_SESSION['error'] = 'Duplicate tag number: '.$tag.' already exists for a '.ucfirst($species).' in this farm.';
    } else {
      log_app_error('ruminant_animal_save_failed',['error'=>$e->getMessage(),'tag_no'=>$tag,'species'=>$species]);
      $_SESSION['error'] = 'The animal could not be saved. Please try again.';
    }
    header('Location: animal_registry.php'); exit();
  }
  $_SESSION['success'] = $id>0 ? 'Animal updated successfully.' : 'Animal added successfully.';
  header('Location: animal_registry.php'); exit();
 }
 if($action==='delete'){
  $id=(int)($_POST['id']??0); $q=$pdo->prepare('SELECT * FROM ruminant_animals WHERE id=? AND farm_id=?'); $q->execute([$id,$farmId]); $before=$q->fetch(PDO::FETCH_ASSOC); if(!$before) exit('Animal not found.');
  $q=$pdo->prepare("UPDATE ruminant_animals SET status='culled', updated_at=NOW() WHERE id=? AND farm_id=?"); $q->execute([$id,$farmId]); audit_log_event('status_change','ruminant_animal',$id,['before'=>$before,'status'=>'culled']); header('Location: animal_registry.php'); exit();
 }
}
$species=$_GET['species']??''; $status=$_GET['status']??'active';
$sql='SELECT * FROM ruminant_animals WHERE farm_id=?'; $params=[$farmId];
if($species!==''&&in_array($species,['cattle','goat','sheep','other'],true)){ $sql.=' AND species=?'; $params[]=$species; }
if($status!==''&&in_array($status,['active','sold','dead','culled','transferred'],true)){ $sql.=' AND status=?'; $params[]=$status; }
$sql.=' ORDER BY species,tag_no'; $q=$pdo->prepare($sql); $q->execute($params); $animals=$q->fetchAll(PDO::FETCH_ASSOC);
$summary=$pdo->prepare('SELECT species,status,COUNT(*) c FROM ruminant_animals WHERE farm_id=? GROUP BY species,status'); $summary->execute([$farmId]); $counts=[]; foreach($summary as $r){$counts[$r['species']][$r['status']]=(int)$r['c'];}
?>
<!doctype html><html lang="en"><head><?php include(__DIR__.'/../navbar_head.php'); ?><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ruminant Animal Registry</title></head><body class="ruminant-page"><?php include(__DIR__.'/../navbar.php'); ?><main class="container-fluid mt-4 poultry-shell"><div class="card poultry-panel"><div class="card-header poultry-hero d-flex justify-content-between align-items-center"><h4 class="mb-0"><i class="bi bi-tags"></i> Ruminant Animal Registry</h4><?php if($canManage): ?><button class="btn btn-light" data-bs-toggle="modal" data-bs-target="#animalModal">Add Animal</button><?php endif; ?></div><div class="card-body"><div class="row g-3 mb-4"><div class="col-6 col-xl"><div class="card h-100"><div class="card-body"><small>Active animals</small><h3><?php echo array_sum(array_map(fn($x)=>$x['active']??0,$counts)); ?></h3></div></div></div><?php foreach(['cattle','goat','sheep','other'] as $sp): ?><div class="col-6 col-xl"><div class="card h-100"><div class="card-body"><small><?php echo ucfirst($sp); ?></small><h3><?php echo (int)($counts[$sp]['active']??0); ?></h3></div></div></div><?php endforeach; ?></div><form class="row g-2 mb-3"><div class="col-md-4"><select class="form-select" name="species"><option value="">All species</option><?php foreach(['cattle','goat','sheep','other'] as $sp): ?><option value="<?php echo $sp; ?>" <?php echo $species===$sp?'selected':''; ?>><?php echo ucfirst($sp); ?></option><?php endforeach; ?></select></div><div class="col-md-4"><select class="form-select" name="status"><option value="">All statuses</option><?php foreach(['active','sold','dead','culled','transferred'] as $st): ?><option value="<?php echo $st; ?>" <?php echo $status===$st?'selected':''; ?>><?php echo ucfirst($st); ?></option><?php endforeach; ?></select></div><div class="col-md-2"><button class="btn btn-outline-primary w-100">Filter</button></div></form><div class="table-responsive"><table class="table table-striped"><thead><tr><th>Tag</th><th>Species</th><th>Breed</th><th>Sex</th><th>Birth</th><th>Purchase cost</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($animals as $a): ?><tr><td><strong><?php echo htmlspecialchars($a['tag_no']); ?></strong></td><td><?php echo ucfirst($a['species']); ?></td><td><?php echo htmlspecialchars($a['breed']??'--'); ?></td><td><?php echo ucfirst($a['sex']); ?></td><td><?php echo $a['birth_date']?date('d/m/Y',strtotime($a['birth_date'])):'--'; ?></td><td>₦<?php echo number_format((float)$a['purchase_cost'],2); ?></td><td><span class="badge text-bg-<?php echo $a['status']==='active'?'success':'secondary'; ?>"><?php echo ucfirst($a['status']); ?></span></td><td class="text-nowrap"><a class="btn btn-sm btn-outline-secondary" href="animal_view.php?id=<?php echo (int)$a['id']; ?>">View</a><?php if($canManage): ?> <button class="btn btn-sm btn-outline-primary" onclick='editAnimal(<?php echo json_encode($a,JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_AMP); ?>)'>Edit</button><?php if($a['status']==='active'): ?> <form method="post" class="d-inline" data-confirm="Mark this animal as culled? This will keep the animal in the registry with Culled status." data-confirm-title="Cull animal?" data-confirm-button="Cull"><input type="hidden" name="csrf_token" value="<?php echo htmlspecialchars(csrf_token(),ENT_QUOTES); ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?php echo (int)$a['id']; ?>"><button class="btn btn-sm btn-outline-danger">Cull</button></form><?php endif; ?><?php endif; ?></td></tr><?php endforeach; if(!$animals): ?><tr><td colspan="8" class="text-center text-muted">No animals found.</td></tr><?php endif; ?></tbody></table></div></div></div></main><?php if($canManage): ?><div class="modal fade" id="animalModal"><div class="modal-dialog modal-lg"><div class="modal-content"><form method="post"><div class="modal-header"><h5 class="modal-title">Ruminant Animal</h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><input type="hidden" name="csrf_token" value="<?php echo htmlspecialchars(csrf_token(),ENT_QUOTES); ?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" id="animal_id"><div class="row g-3"><div class="col-md-4"><label class="form-label">Tag No *</label><input class="form-control" name="tag_no" id="tag_no" required><div class="form-text">Unique within this species. For example, Cattle #1 and Goat #1 can both exist.</div></div><div class="col-md-4"><label class="form-label">Species</label><select class="form-select" name="species" id="species"><?php foreach(['cattle','goat','sheep','other'] as $sp): ?><option value="<?php echo $sp; ?>"><?php echo ucfirst($sp); ?></option><?php endforeach; ?></select></div><div class="col-md-4"><label class="form-label">Sex</label><select class="form-select" name="sex" id="sex"><option>unknown</option><option>male</option><option>female</option></select></div><div class="col-md-4"><label class="form-label">Breed</label><input class="form-control" name="breed" id="breed"></div><div class="col-md-4"><label class="form-label">Birth date</label><input type="date" class="form-control" name="birth_date" id="birth_date"></div><div class="col-md-4"><label class="form-label">Purchase date</label><input type="date" class="form-control" name="purchase_date" id="purchase_date"></div><div class="col-md-4"><label class="form-label">Purchase cost</label><input type="number" min="0" step="0.01" class="form-control" name="purchase_cost" id="purchase_cost"></div><div class="col-md-4"><label class="form-label">Source</label><input class="form-control" name="source" id="source"></div><div class="col-md-4"><label class="form-label">Status</label><select class="form-select" name="status" id="status"><?php foreach(['active','sold','dead','culled','transferred'] as $st): ?><option value="<?php echo $st; ?>"><?php echo ucfirst($st); ?></option><?php endforeach; ?></select></div><div class="col-12"><label class="form-label">Notes</label><textarea class="form-control" name="notes" id="notes" rows="3"></textarea></div></div></div><div class="modal-footer"><button class="btn btn-primary">Save Animal</button></div></form></div></div></div><script src="<?php echo BASE_URL; ?><?php echo versioned_asset('/assets/vendor/bootstrap5/js/bootstrap.bundle.min.js'); ?>"></script><script>function editAnimal(a){for(const k of ['id','tag_no','species','sex','breed','birth_date','purchase_date','purchase_cost','source','status','notes']){const e=document.getElementById('animal_'+k)||document.getElementById(k);if(e)e.value=a[k]??'';}bootstrap.Modal.getOrCreateInstance(document.getElementById('animalModal')).show();}
<?php if($editAnimal): ?>document.addEventListener('DOMContentLoaded',function(){editAnimal(<?php echo json_encode($editAnimal,JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_AMP); ?>);});<?php endif; ?></script><?php endif; ?></body></html>
